/**
 * 录音预览页右侧固定悬浮按钮组（/recording/preview/:fileId）。
 *
 * 洞察生成完成后显示（由 RecordingPreview 按 AudioView 上报的 insightDone 控制），
 * 悬浮于内容区右侧边缘、垂直居中，不随内容滚动：
 * - 第一组：提议 / 行动 / 成果 —— 贴右边缘圆角卡片，计数来自统一事项接口，
 *   点击在右侧 Flutter 面板打开对应阶段的行动事项抽屉；
 * - 第二组：探讨 —— 贴右边缘圆角卡片，点击打开右侧 375px Flutter Web 面板。
 */
export function PreviewInsightDock({ onDiscuss, onOpenActionItems, counts }: PreviewInsightDockProps) {
  const { proposal = 0, action = 0, deliverable = 0 } = counts || {}

  return (
    <div className="absolute right-0 top-1/2 z-20 flex -translate-y-1/2 flex-col items-end gap-3 select-none">
      {/* 第一组：提议 / 行动 / 成果 */}
      <div className="flex w-[58px] flex-col items-center rounded-l-2xl border-y border-l border-[#E9EBF2] bg-white py-1 shadow-[-2px_0_12px_rgba(0,0,0,0.06)]">
        {/* 提议 */}
        <Tooltip title="查看提议" placement="left">
          <button
            type="button"
            onClick={() => onOpenActionItems('proposal')}
            className="flex h-[56px] w-full flex-col items-center justify-center gap-1.5 text-[#6B7280] transition-colors hover:text-[#1D1E1F]"
          >
            <ProposalIcon className="size-[18px]" />
            <span className="text-xs leading-none">提议({proposal})</span>
          </button>
        </Tooltip>

        {/* 行动 */}
        <Tooltip title="查看行动" placement="left">
          <button
            type="button"
            onClick={() => onOpenActionItems('action')}
            className="flex h-[56px] w-full flex-col items-center justify-center gap-1.5 text-[#6B7280] transition-colors hover:text-[#1D1E1F]"
          >
            <ActionIcon className="size-[18px]" />
            <span className="text-xs leading-none">行动({action})</span>
          </button>
        </Tooltip>

        {/* 成果 */}
        <Tooltip title="查看成果" placement="left">
          <button
            type="button"
            onClick={() => onOpenActionItems('result')}
            className="flex h-[56px] w-full flex-col items-center justify-center gap-1.5 text-[#6B7280] transition-colors hover:text-[#1D1E1F]"
          >
            <ResultIcon className="size-[18px]" />
            <span className="text-xs leading-none">成果({deliverable})</span>
          </button>
        </Tooltip>
      </div>

      {/* 第二组：探讨 */}
      <div className="flex w-[58px] flex-col items-center rounded-l-2xl border-y border-l border-[#E9EBF2] bg-white shadow-[-2px_0_12px_rgba(0,0,0,0.06)]">
        <Tooltip title="打开探讨" placement="left">
          <button
            type="button"
            onClick={onDiscuss}
            className="flex h-[58px] w-full flex-col items-center justify-center gap-1.5 text-[#6B7280] transition-colors hover:text-[#2563EB]"
          >
            <DiscussIcon className="size-[18px]" />
            <span className="text-xs leading-none">探讨</span>
          </button>
        </Tooltip>
      </div>
    </div>
  )
}

